1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	};
49	
50	const quotePremium = (items: Item[]): number => {
51	  const policyBase = items.reduce(
52	    (sum, item) => sum + BASE_PREMIUMS[item.type],
53	    0,
54	  );
55	  const surcharge = percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
56	  return Math.ceil(policyBase + surcharge + PROCESSING_FEE);
57	};
58	
59	const runStep = (step: Step): StepResult => {
60	  if (step.op === "quote") return { premium: quotePremium(step.items) };
61	  throw new Error("claim steps are not implemented yet");
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioResult => ({
65	  results: scenario.steps.map(runStep),
66	});
