const policyBasePremium = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const quotePremium = (items: Item[]): number => {
  const base = policyBasePremium(items);
  const surcharge = percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return Math.ceil(base + surcharge + PROCESSING_FEE);
};
